mapper.select:
WITH date_param AS ( SELECT REPLACE(#{from_yyyymm}, '-', '') || '01' AS from_date , TO_CHAR( DATE_TRUNC('month', TO_DATE(REPLACE(#{to_yyyymm}, '-', ''), 'YYYYMM')) + INTERVAL '1 month - 1 day', 'YYYYMMDD' ) AS to_date ), latest_change AS ( SELECT company_code, key_no, content FROM ( SELECT ch.company_code , ch.key_no , ch.content , ROW_NUMBER() OVER ( PARTITION BY ch.company_code, ch.key_no ORDER BY ch.create_date DESC, ch.change_seq DESC ) AS rn FROM public.change_history ch WHERE ch.program_id = 'cooIssueCertModifyForm' ) t WHERE t.rn = 1 ), target_product AS ( SELECT * FROM ( SELECT sd.company_code , sd.division_code , sd.sales_no , sd.sales_seq , sd.order_no , sd.product_code , sd.product_name , sd.hs_code , sd.prod_division_code , sd.delivery_customer_code , ROW_NUMBER() OVER ( PARTITION BY sd.company_code, sd.division_code, sd.sales_no ORDER BY sd.sales_seq ) AS rn FROM public.sales_dtl sd WHERE sd.status = '4' AND sd.coo_certify_no IS NULL ) t WHERE t.rn = 1 ), target_list AS ( SELECT di.division_name , sm.division_code , sm.sales_no , NULL::varchar(30) AS coo_certify_no , sm.invoice_no , sm.bl_no , cd.code_name AS co_issue_flag_name , sm.export_flag , sm.invoice_date , sm.customer_code , cu.customer_name , TO_CHAR(sm.coo_date, 'YYYY-MM-DD') AS coo_date , sm.target_fta_code AS fta_code , fm.fta_name , fm.co_issue_flag , fm.cover_yn , sm.ship_invoice_no , tp.order_no , tp.product_code , tp.product_name , tp.sales_seq , 'NOT_ISSUED'::varchar(20) AS issue_status , '미발급'::varchar(50) AS issue_status_name , NULL::varchar(4000) AS modify_issue_reason , SUBSTRING(sm.invoice_date, 1, 6) AS yyyymm FROM public.sales_mst sm JOIN target_product tp ON tp.company_code = sm.company_code AND tp.division_code = sm.division_code AND tp.sales_no = sm.sales_no JOIN public.customer cu ON cu.customer_code = sm.customer_code AND cu.company_code = sm.company_code JOIN public.division di ON di.division_code = sm.division_code AND di.company_code = sm.company_code LEFT JOIN public.fta_master fm ON fm.fta_code = sm.target_fta_code AND fm.company_code = sm.company_code AND fm.delete_yn = 'N' LEFT JOIN public.code_dtl cd ON cd.company_code = sm.company_code AND cd.code = fm.co_issue_flag AND cd.category = 'CI'
JOIN public.customer_model cm ON cm.company_code = tp.company_code AND cm.item_code = tp.product_code AND cm.division_code = tp.prod_division_code AND cm.customer_code = tp.delivery_customer_code
CROSS JOIN date_param dp WHERE sm.status = '4' AND sm.export_flag = 'E' AND sm.company_code = #{company_code} AND sm.invoice_date BETWEEN dp.from_date AND dp.to_date AND sm.coo_certify_no IS NULL
AND sm.customer_code = #{customer_code}
AND sm.division_code = #{division_code}
AND tp.product_code LIKE '%' || #{search_keyword} || '%'
AND cm.customer_item_code LIKE '%' || #{search_keyword} || '%'
AND tp.sales_no LIKE #{search_keyword} || '%'
AND 1 = 0
), issued_product AS ( SELECT * FROM ( SELECT cld.coo_certify_no , cld.company_code , cld.division_code , cld.sales_no , cld.sales_seq , cld.fta_code , cld.product_code , sd.product_name , sd.order_no , sd.hs_code , sd.prod_division_code , sd.delivery_customer_code , ROW_NUMBER() OVER ( PARTITION BY cld.company_code, cld.division_code, cld.sales_no, cld.coo_certify_no ORDER BY cld.sales_seq ) AS rn FROM public.coo_certify_ledger_dtl cld JOIN public.sales_dtl sd ON sd.company_code = cld.company_code AND sd.division_code = cld.division_code AND sd.sales_no = cld.sales_no AND sd.sales_seq = cld.sales_seq ) t WHERE t.rn = 1 ), issued_detail AS ( SELECT di.division_name , cl.division_code , ip.sales_no , cl.coo_certify_no , sm.invoice_no , sm.bl_no , cd.code_name AS co_issue_flag_name , cl.export_flag , sm.invoice_date , cl.customer_code , cu.customer_name , TO_CHAR(TO_DATE(cl.issue_date, 'YYYYMMDD'), 'YYYY-MM-DD') AS coo_date , ip.fta_code , fm.fta_name , fm.co_issue_flag , fm.cover_yn , sm.ship_invoice_no , ip.order_no , ip.product_code , ip.product_name , ip.sales_seq , CASE WHEN (cl.origin_coo_certify_no IS NOT NULL AND TRIM(cl.origin_coo_certify_no) <> '') OR (lc.content IS NOT NULL AND TRIM(lc.content) <> '') THEN 'MODIFIED' ELSE 'ISSUED' END AS issue_status , CASE WHEN (cl.origin_coo_certify_no IS NOT NULL AND TRIM(cl.origin_coo_certify_no) <> '') OR (lc.content IS NOT NULL AND TRIM(lc.content) <> '') THEN '수정' ELSE '발급' END AS issue_status_name , lc.content AS modify_issue_reason , SUBSTRING(sm.invoice_date, 1, 6) AS yyyymm FROM public.coo_certify_ledger cl JOIN issued_product ip ON ip.coo_certify_no = cl.coo_certify_no AND ip.company_code = cl.company_code AND ip.division_code = cl.division_code JOIN public.sales_mst sm ON sm.company_code = ip.company_code AND sm.division_code = ip.division_code AND sm.sales_no = ip.sales_no JOIN public.customer cu ON cu.customer_code = cl.customer_code AND cu.company_code = cl.company_code JOIN public.division di ON di.division_code = cl.division_code AND di.company_code = cl.company_code LEFT JOIN public.fta_master fm ON fm.fta_code = ip.fta_code AND fm.delete_yn = 'N' AND fm.company_code = cl.company_code LEFT JOIN public.code_dtl cd ON cd.company_code = cl.company_code AND cd.code = fm.co_issue_flag AND cd.category = 'CI' LEFT JOIN latest_change lc ON lc.company_code = cl.company_code AND lc.key_no = cl.coo_certify_no
JOIN public.customer_model cm ON cm.company_code = ip.company_code AND cm.item_code = ip.product_code AND cm.division_code = ip.prod_division_code AND cm.customer_code = ip.delivery_customer_code
CROSS JOIN date_param dp WHERE cl.company_code = #{company_code} AND cl.issue_date BETWEEN dp.from_date AND dp.to_date
AND cl.customer_code = #{customer_code}
AND cl.division_code = #{division_code}
AND ip.product_code LIKE '%' || #{search_keyword} || '%'
AND cm.customer_item_code LIKE '%' || #{search_keyword} || '%'
AND cl.coo_certify_no LIKE '%' || #{search_keyword} || '%'
) SELECT DISTINCT division_name , division_code , sales_no , coo_certify_no , invoice_no , bl_no , co_issue_flag_name , export_flag , TO_CHAR(TO_DATE(invoice_date, 'YYYYMMDD'), 'YYYY-MM-DD') AS invoice_date , customer_code , customer_name , coo_date , fta_code , fta_name , co_issue_flag , cover_yn , ship_invoice_no , order_no , product_code , product_name , sales_seq , issue_status , issue_status_name , modify_issue_reason , yyyymm FROM ( SELECT * FROM target_list UNION ALL SELECT * FROM issued_detail ) a
a.issue_status = #{issue_status}
ORDER BY customer_code , division_code , yyyymm , sales_no , coo_certify_no NULLS FIRST

SELECT #{division_code}
       || '-' || #{export_flag}
       || '-' || TO_CHAR(CURRENT_DATE, 'YYMMDD')
       || '-' ||
       (
           SELECT LPAD(
                      (
                          COALESCE(
                              MAX(
                                  CASE
                                      WHEN REPLACE(
                                               coo_certify_no,
                                               #{division_code}
                                               || '-' || #{export_flag}
                                               || '-' || TO_CHAR(CURRENT_DATE, 'YYMMDD')
                                               || '-',
                                               ''
                                           ) ~ '^[0-9]+$'
                                      THEN CAST(
                                               REPLACE(
                                                   coo_certify_no,
                                                   #{division_code}
                                                   || '-' || #{export_flag}
                                                   || '-' || TO_CHAR(CURRENT_DATE, 'YYMMDD')
                                                   || '-',
                                                   ''
                                               ) AS integer
                                           )
                                      ELSE NULL
                                  END
                              ),
                              0
                          ) + 1
                      )::text,
                      4,
                      '0'
                  )
           FROM coo_certify_ledger
           WHERE company_code = #{company_code}
             AND division_code = #{division_code}
             AND coo_certify_no LIKE #{division_code}
                                   || '-' || #{export_flag}
                                   || '-' || TO_CHAR(CURRENT_DATE, 'YYMMDD')
                                   || '-%'
       ) AS coo_certify_no

mapper.update:
UPDATE sales_dtl sm
   SET coo_type = #{coo_type}
     , coo_certify_no = #{coo_certify_no}
     , update_date = CURRENT_TIMESTAMP
     , update_by = #{update_by}
 WHERE EXISTS (
        SELECT 1
        FROM coo_certify_ledger_dtl a
        WHERE a.sales_no = sm.sales_no
          AND a.sales_seq = sm.sales_seq
          AND a.division_code = sm.division_code
          AND a.company_code = sm.company_code
          AND a.coo_certify_no = #{coo_certify_no}
 )

UPDATE prod_sales_dtl sm
   SET coo_type = #{coo_type}
     , coo_certify_no = #{coo_certify_no}
     , update_date = CURRENT_TIMESTAMP
     , update_by = #{update_by}
 WHERE EXISTS (
        SELECT 1
        FROM coo_certify_ledger_dtl a
        WHERE a.sales_no = sm.sales_no
          AND a.sales_seq = sm.sales_seq
          AND a.division_code = sm.division_code
          AND a.company_code = sm.company_code
          AND a.coo_certify_no = #{coo_certify_no}
 )

