    INSERT INTO change_history
    (
        program_id
      , key_no
      , change_seq
      , company_code
      , content
      , attribute01
      , create_date
      , create_by
      , update_date
      , update_by
    )
    SELECT
          #{program_id}
        , #{coo_certify_no}
        , COALESCE(MAX(change_seq), 0) + 1
        , #{company_code}
        , #{modify_issue_reason}
        , #{origin_coo_certify_no}
        , CURRENT_TIMESTAMP
        , #{create_by}
        , CURRENT_TIMESTAMP
        , #{update_by}
    FROM change_history
    WHERE program_id = #{program_id}
      AND key_no = #{coo_certify_no}
      AND company_code = #{company_code}
